"""Generate the complete static website. Run: python build.py (standard library only)."""
import json, re, html
from pathlib import Path
ROOT = Path(__file__).resolve().parent
BOOK = 'https://www.hisawyer.com/dance-institute-denver/schedules/membership-plans'
PHOTO = 'https://www.danceinstitutedenver.com/wp-content/uploads/2026/07/'
classes = json.loads((ROOT / 'classes.json').read_text())

def class_rows():
    rows = []
    for c in classes:
        style = {'combo':'Combination','hiphop':'Hip-hop','tap':'Tap','ballet':'Ballet','jazz':'Advanced training','theater':'Musical theater','technique':'Technique'}[c['styles'].split()[0]]
        rows.append(f'''<details class="class-item" data-styles="{c['styles']}" data-min="{c['min'] if c['min'] is not None else ''}" data-max="{c['max'] if c['max'] is not None else ''}" data-audience="{c['audience']}" data-search="{html.escape((c['name']+' '+c['description']+' '+c['styles']).lower(),quote=True)}"><summary><span class="class-name">{c['name']}<small>{style}</small></span><span class="class-age">{c['age']}</span><span class="class-duration">{c['duration']}</span><span class="expand-icon" aria-hidden="true">+</span></summary><div class="class-detail"><p>{c['description']}</p><div><a href="@/class-schedule/">Check schedule <span aria-hidden="true">↗</span></a><a href="@/registration/">Registration <span aria-hidden="true">↗</span></a></div></div></details>''')
    return '\n'.join(rows)

home = {'slug':'','title':'Dance Institute of Denver','section':'Home','description':'Dance classes for children, teens and adults.','body':f'''
<div class="home-studio"><figure class="studio-window"><img src="{PHOTO}dance-class-main-1200x459-c-default.webp" width="1200" height="459" alt="Dance photography from Dance Institute of Denver" fetchpriority="high"><figcaption>Dance Institute <span>Denver, Colorado</span></figcaption></figure><section class="studio-desk" aria-labelledby="start-title"><p class="eyebrow">THE STUDIO DESK</p><h2 id="start-title">How can we<br>help you?</h2><div class="desk-links"><a href="@/adult-kids-dance-classes/"><span><strong>Find a class</strong><small>Ages, styles & class lengths</small></span><span aria-hidden="true">↗</span></a><a href="@/class-schedule/"><span><strong>View the schedule</strong><small>Times & current availability</small></span><span aria-hidden="true">↗</span></a><a href="@/registration/"><span><strong>Register or try a class</strong><small>Tuition, memberships & first visits</small></span><span aria-hidden="true">↗</span></a></div></section></div>
<div class="home-lower"><section class="prose"><p class="eyebrow">ABOUT THE STUDIO</p><h2>Dance training.<br>A welcoming room.</h2><p>We teach technique in a friendly, encouraging atmosphere, with classes for young children through adults.</p><p>Parents can watch class. Combination programs let children try several styles together. Our school year runs September through June, ending with the annual recital.</p><a class="inline-link" href="@/about/">Get to know the studio ↗</a></section><section class="notice-board" aria-labelledby="notice-title"><p class="eyebrow">GOOD TO KNOW</p><h2 id="notice-title">Before you visit</h2><div class="notice"><span class="note-dot" aria-hidden="true"></span><div><h3>First time here?</h3><p>One free trial class is available through Sawyer.</p><a href="@/registration/">See how to start →</a></div></div><div class="notice"><span class="note-dot" aria-hidden="true"></span><div><h3>Preparing for class</h3><p>Check the clothing, shoes and hair guidelines.</p><a href="@/about/studio-policies/">Read studio policies →</a></div></div><div class="notice"><span class="note-dot" aria-hidden="true"></span><div><h3>Find us</h3><p>10515 E 40th Ave, #114<br>Denver, CO 80239</p><a href="@/contact/">Directions & contact →</a></div></div></section></div>'''}
classpage = {'slug':'adult-kids-dance-classes/','title':'Dance classes','section':'Dance Classes','description':'Compare programs by age, style and class length.','body':f'''
<div class="page-actions"><a class="button" href="@/class-schedule/">View schedule ↗</a><a class="button button-secondary" href="@/registration/">Tuition & registration ↗</a></div>
<section class="class-finder" aria-label="Class directory"><form id="class-filters" class="finder-controls" hidden><div><label for="class-search">Search classes</label><input id="class-search" type="search" placeholder="Ballet, tap, hip-hop…" autocomplete="off"></div><div><label for="age-filter">Dancer’s age</label><select id="age-filter"><option value="all">All ages</option><option value="baby">Babies & toddlers</option><option value="3-5">3–5 years</option><option value="6-9">6–9 years</option><option value="10-13">10–13 years</option><option value="14-17">14–17 years</option><option value="adult">Adults</option><option value="placement">By placement</option></select></div><div><label for="style-filter">Dance style</label><select id="style-filter"><option value="all">All styles</option><option value="combo">Combination</option><option value="ballet">Ballet & pointe</option><option value="tap">Tap</option><option value="hiphop">Hip-hop</option><option value="jazz">Jazz</option><option value="lyrical">Lyrical</option><option value="contemporary">Contemporary</option><option value="theater">Musical theater</option><option value="technique">Leaps, turns & tricks</option></select></div><button type="reset" class="reset-button">Reset</button></form><div class="directory-meta"><p id="results-count" role="status" aria-live="polite">16 programs</p><span>Select a class for details</span></div><div class="directory-head" aria-hidden="true"><span>PROGRAM</span><span>AGE / LEVEL</span><span>LENGTH</span><span></span></div><div id="class-list">{class_rows()}</div><div id="no-results" class="empty-state" hidden><h2>No matching classes</h2><p>Try another age or style, or clear your filters.</p><button type="button" id="clear-filters" class="button">Show all classes</button></div><p id="placement-note" class="note" hidden>Some programs require instructor placement. Choose “By placement” under dancer’s age to explore those options.</p></section><div class="help-strip"><div><strong>Need help choosing a level?</strong><span>Call the studio for placement and current availability.</span></div><a href="tel:+13035250011">(303) 525-0011 ↗</a></div>'''}

NAV = [('Home',''),('Dance Classes','adult-kids-dance-classes/'),('About','about/'),('Schedule',None),('Nutcracker','nutcracker/'),('Register','registration/'),('Contact','contact/')]
SUBS = {'About':[('Studio Policies','about/studio-policies/'),('Teachers','about/teachers/'),('Partners','about/partners/')], 'Schedule':[('Dance Schedule','class-schedule/'),('Summer Schedule','summer-schedule/')]}

def shell(page):
    slug=page['slug']; depth=len([p for p in slug.split('/') if p]); base='../'*depth or './'
    def route(target): return base+target
    nav=''
    for label,target in NAV:
        active=(target==slug) if target is not None else slug in ['class-schedule/','summer-schedule/']
        if label in SUBS:
            expanded=(label=='About' and slug.startswith('about/')) or (label=='Schedule' and active)
            nav+=f'<div class="nav-group"><div class="nav-group-top">'+(f'<a href="{route(target)}"'+(' aria-current="page"' if active else '')+f'>{label}</a>' if target is not None else f'<span>{label}</span>')+f'<button class="subnav-toggle" aria-label="Toggle {label.lower()} pages" aria-controls="subnav-{label.lower()}" aria-expanded="true" hidden><span aria-hidden="true">−</span></button></div><div class="subnav" id="subnav-{label.lower()}" data-default-open="{str(expanded).lower()}">'
            for text,url in SUBS[label]: nav+=f'<a href="{route(url)}"'+(' aria-current="page"' if slug==url else '')+f'>{text}</a>'
            nav+='</div></div>'
        else: nav+=f'<a href="{route(target)}"'+(' aria-current="page"' if active else '')+f'>{label}<span aria-hidden="true">↗</span></a>'
    title=html.escape(page['title']);description=html.escape(page['description']);body=re.sub(r'@/([^"\s<>]*)',lambda m:route(m.group(1)),page['body'])
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#203b2e"><meta name="description" content="{description}"><title>{title}{' | Dance Institute of Denver' if slug else ''}</title><link rel="icon" href="{base}favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Libre+Caslon+Display&display=swap" rel="stylesheet"><link rel="stylesheet" href="{base}styles.css"><script src="{base}script.js" defer></script></head><body>
<a class="skip-link" href="#main">Skip to content</a><aside class="studio-nav"><div class="brand-row"><a class="wordmark" href="{base}" aria-label="Dance Institute of Denver home"><span class="brand-emblem" aria-hidden="true">DI</span><span>Dance<br>Institute<small>DENVER, COLORADO</small></span></a><button class="menu-toggle" aria-controls="site-navigation" aria-expanded="true" hidden>Menu <span aria-hidden="true">−</span></button></div><div id="site-navigation" class="navigation-content"><p class="nav-label">THE STUDIO</p><nav aria-label="Main navigation">{nav}</nav><div class="sidebar-bottom"><a class="register-link" href="{route('registration/')}">Register for a class <span aria-hidden="true">↗</span></a><a class="sidebar-phone" href="tel:+13035250011">(303) 525-0011</a><address>10515 E 40th Ave, #114<br>Denver, CO 80239</address></div></div></aside>
<div class="page-shell"><header class="utility-bar"><span>{html.escape(page['section'])}</span><div><a href="{route('class-schedule/')}">Class schedule</a><span aria-hidden="true">/</span><a href="tel:+13035250011">(303) 525-0011</a></div></header><main id="main" tabindex="-1"><div class="page-heading"><div><p class="eyebrow">DANCE INSTITUTE OF DENVER</p><h1>{title}</h1><p class="page-description">{description}</p></div><span class="heading-mark" aria-hidden="true">di.</span></div>{body}</main><footer class="footer"><span>© <span data-year>2026</span> Dance Institute of Denver</span><div><a href="{route('sitemap/')}">Sitemap</a><a href="{route('privacy-policy/')}">Privacy policy</a><a href="{route('contact/')}">Contact</a></div></footer></div>
</body></html>'''

if __name__=='__main__':
    pages=[home,classpage]+json.loads((ROOT/'page-content.json').read_text())
    pages.append({'slug':'sitemap/','title':'Sitemap','section':'Sitemap','description':'All studio pages.','body':'<div class="link-list">'+''.join(f'<a href="@/{p["slug"]}">{html.escape(p["title"])} <span aria-hidden="true">↗</span></a>' for p in pages)+'</div>'})
    for page in pages:
        destination=ROOT/page['slug']/'index.html';destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(shell(page))
    print(f'Built {len(pages)} static pages.')
